// ──────────────────────────── tests ──────────────────────────────────────

test('resolves with whatever the child printed to stdout', async () => {
  const { stdout } = await runNode("process.stdout.write('hi from the child')");
  eq(stdout, 'hi from the child');
});

test('keeps stderr separate from stdout', async () => {
  const result = await runNode(
    "process.stdout.write('out'); process.stderr.write('err');"
  );
  eq(result.stdout, 'out');
  eq(result.stderr, 'err');
});

test('a non-zero exit rejects instead of resolving', async () => {
  await rejects(() => runNode('process.exit(3)'));
});

test('tryRunNode reports success and the output', async () => {
  eq(await tryRunNode("process.stdout.write('all good')"), {
    ok: true,
    stdout: 'all good',
  });
});

test('tryRunNode reports the exit code instead of throwing', async () => {
  eq(await tryRunNode("process.stderr.write('nope'); process.exit(3);"), {
    ok: false,
    code: 3,
    stderr: 'nope',
  });
});

test('the child really is a separate process', async () => {
  const { stdout } = await runNode('process.stdout.write(String(process.pid))');
  ok(Number(stdout) !== process.pid, 'child pid should differ from ours');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('collects what the child wrote to stdout', async () => {
  const result = await spawnNode("process.stdout.write('hello')");
  eq(result.out, 'hello');
  eq(result.code, 0);
});

test('collects stderr separately', async () => {
  const result = await spawnNode("process.stderr.write('warned')");
  eq(result.err, 'warned');
  eq(result.out, '');
});

test('reports a non-zero exit code instead of rejecting', async () => {
  const result = await spawnNode("process.stdout.write('bye'); process.exit(2);");
  eq(result.code, 2);
  eq(result.out, 'bye');
});

test('keeps every chunk, even when they arrive far apart', async () => {
  const result = await spawnNode(
    "process.stdout.write('a'); setTimeout(() => process.stdout.write('b'), 25);"
  );
  eq(result.out, 'ab');
});

test('the chunks join back into the full output', async () => {
  const result = await spawnNode("process.stdout.write('chunky')");
  ok(Array.isArray(result.chunks), 'chunks should be an array');
  ok(result.chunks.length >= 1, 'expected at least one chunk');
  eq(result.chunks.join(''), result.out);
});

test('a silent program gives empty strings, not undefined', async () => {
  const result = await spawnNode('0;');
  eq(result.out, '');
  eq(result.err, '');
  eq(result.code, 0);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('shouts back what you sent', async () => {
  eq(await uppercaseInChild('hello'), 'HELLO');
});

test('an empty payload comes back empty — you closed stdin', async () => {
  eq(await uppercaseInChild(''), '');
});

test('newlines and punctuation survive the round trip', async () => {
  eq(await uppercaseInChild('one\ntwo!\n'), 'ONE\nTWO!\n');
});

test('digits and symbols are passed through unchanged', async () => {
  eq(await uppercaseInChild('a1-b2 %'), 'A1-B2 %');
});

test('a payload bigger than one chunk arrives whole', async () => {
  const big = 'ab'.repeat(1500);
  const result = await uppercaseInChild(big);
  eq(result.length, big.length);
  eq(result, big.toUpperCase());
});

test('two runs do not share state', async () => {
  const [first, second] = await Promise.all([
    uppercaseInChild('first'),
    uppercaseInChild('second'),
  ]);
  eq(first, 'FIRST');
  eq(second, 'SECOND');
  ok(first !== second, 'each child should answer its own input');
});

