test('returns one result per source, in input order', async () => {
  resetStats();
  const sources = ['a', 'b', 'c'].map(prints);
  eq(await runAll(sources, 2), ['a', 'b', 'c']);
  eq(stats.started, 3);
});

test('never runs more children than the limit allows', async () => {
  resetStats();
  const sources = ['x', 'y', 'z'].map(prints);
  await runAll(sources, 2);
  eq(stats.peak, 2);
});

test('a limit of 1 runs them strictly one at a time', async () => {
  resetStats();
  eq(await runAll(['one', 'two'].map(prints), 1), ['one', 'two']);
  eq(stats.peak, 1);
});

test('an empty list resolves to an empty array and starts nothing', async () => {
  resetStats();
  eq(await runAll([], 2), []);
  eq(stats.started, 0);
});

test('a limit larger than the list is not a problem', async () => {
  resetStats();
  eq(await runAll(['p', 'q'].map(prints), 5), ['p', 'q']);
  eq(stats.started, 2);
  ok(stats.peak <= 2, 'cannot run more children than there are sources');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('counts the primes up to 10', async () => {
  eq(await countPrimes(10), 4);
});

test('counts the primes up to 100', async () => {
  eq(await countPrimes(100), 25);
});

test('answers 0 when there is nothing to count', async () => {
  const result = await countPrimes(1);
  eq(result, 0);
  ok(typeof result === 'number', 'the value crosses as a number, not text');
});

test('a worker that dies rejects with its error', async () => {
  await rejects(() => runWorker(BROKEN_WORKER), 'worker exploded');
});

test('two workers can be in flight at once', async () => {
  eq(await Promise.all([countPrimes(10), countPrimes(20)]), [4, 8]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('doubles a number', async () => {
  resetLog();
  const calc = createDoubler();
  try {
    eq(await calc.double(21), 42);
  } finally {
    await calc.close();
  }
});

test('concurrent calls each get their own answer', async () => {
  resetLog();
  const calc = createDoubler();
  try {
    eq(await Promise.all([calc.double(1), calc.double(2), calc.double(3)]), [
      2, 4, 6,
    ]);
    eq(created.length, 1, 'one worker should serve every call');
  } finally {
    await calc.close();
  }
});

test('sequential calls keep working on the same thread', async () => {
  resetLog();
  const calc = createDoubler();
  try {
    eq(await calc.double(5), 10);
    eq(await calc.double(50), 100);
    eq(created.length, 1);
  } finally {
    await calc.close();
  }
});

test('zero and negative numbers are fine', async () => {
  resetLog();
  const calc = createDoubler();
  try {
    eq(await Promise.all([calc.double(0), calc.double(-4)]), [0, -8]);
  } finally {
    await calc.close();
  }
});

test('close() actually shuts the thread down', async () => {
  resetLog();
  const calc = createDoubler();
  eq(await calc.double(1), 2);
  await calc.close();
  await sleep(30);
  eq(exited.length, 1, 'the worker should have exited');
  ok(exited[0] === created[0], 'and it should be the one you started');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('runs an arrow function over the argument', async () => {
  eq(await runInWorker('(n) => n * 3', 7), 21);
});

test('accepts a function expression as the source', async () => {
  eq(await runInWorker('function square(n) { return n * n; }', 6), 36);
});

test('objects cross in both directions as structured clones', async () => {
  eq(
    await runInWorker('(user) => ({ shout: user.name.toUpperCase() })', {
      name: 'ada',
    }),
    { shout: 'ADA' }
  );
});

test('a throw inside the worker becomes a rejection out here', async () => {
  await rejects(
    () => runInWorker("() => { throw new Error('inside boom'); }"),
    'inside boom'
  );
});

test('source that is not valid JavaScript rejects too', async () => {
  await rejects(() => runInWorker('@@@', 1));
});

// ──────────────────────────── tests ──────────────────────────────────────

test('there is no request id outside a request', () => {
  eq(currentRequestId(), undefined);
});

test('the id is readable inside the request', async () => {
  eq(await withRequestId('r-1', async () => currentRequestId()), 'r-1');
});

test('the id survives awaits, several calls deep', async () => {
  eq(await withRequestId('r-2', handleRequest), 'user@r-2');
});

test('two concurrent requests keep separate ids', async () => {
  const [first, second] = await Promise.all([
    withRequestId('r-a', handleRequest),
    withRequestId('r-b', handleRequest),
  ]);
  eq(first, 'user@r-a');
  eq(second, 'user@r-b');
});

test('a nested request shadows the outer one, then restores it', async () => {
  const seen = await withRequestId('outer', async () => {
    const inner = await withRequestId('inner', async () => currentRequestId());
    return [inner, currentRequestId()];
  });
  eq(seen, ['inner', 'outer']);
});

test('the id is still there inside a timer callback', async () => {
  const id = await withRequestId(
    'r-timer',
    () => new Promise((resolve) => setTimeout(() => resolve(currentRequestId()), 10))
  );
  eq(id, 'r-timer');
});

test('withRequestId hands back what fn returns, and lets throws out', async () => {
  eq(await withRequestId('r-3', async () => 42), 42);
  await rejects(
    () => withRequestId('r-4', async () => {
      throw new Error('handler failed');
    }),
    'handler failed'
  );
  ok(currentRequestId() === undefined, 'the context closes again after');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('hands back whatever the function returned', async () => {
  const timed = await timeIt(() => 1 + 1);
  eq(timed.result, 2);
  eq(Object.keys(timed).sort(), ['ms', 'result']);
});

test('awaits async functions before stopping the clock', async () => {
  const { result } = await timeIt(async () => 'done');
  eq(result, 'done');
});

test('ms is a number and never negative', async () => {
  const { ms } = await timeIt(() => 'quick');
  ok(typeof ms === 'number', 'ms should be a number');
  ok(ms >= 0, `ms should not be negative (got ${ms})`);
});

test('ms covers the time the function actually spent', async () => {
  const { ms } = await timeIt(() => sleep(25));
  ok(ms >= 15, `expected roughly 25ms of waiting, got ${ms}`);
});

test('a rejection comes straight back out', async () => {
  await rejects(
    () => timeIt(async () => {
      throw new Error('measured code failed');
    }),
    'measured code failed'
  );
});

test('measureSpan returns the value and records a readable span', () => {
  eq(measureSpan('parse', () => 'parsed'), 'parsed');
  const ms = durationOf('parse');
  ok(typeof ms === 'number', 'durationOf should give a number');
  ok(ms >= 0, 'a span cannot be negative');
});

test('each name gets its own span', () => {
  measureSpan('step-a', () => sleep(0));
  measureSpan('step-b', () => sleep(0));
  ok(typeof durationOf('step-a') === 'number');
  ok(typeof durationOf('step-b') === 'number');
});

test('durationOf is undefined for a name nobody measured', () => {
  eq(durationOf('never-measured'), undefined);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('resolves with the arguments the event carried', async () => {
  const emitter = new EventEmitter();
  setTimeout(() => emitter.emit('ready', 'db', 5432), 5);
  eq(await waitFor(emitter, 'ready'), ['db', 5432]);
});

test('an event with no arguments resolves with an empty array', async () => {
  const emitter = new EventEmitter();
  setTimeout(() => emitter.emit('ready'), 5);
  eq(await waitFor(emitter, 'ready'), []);
});

test('passing no signal at all still works', async () => {
  const emitter = new EventEmitter();
  setTimeout(() => emitter.emit('tick', 1), 5);
  eq(await waitFor(emitter, 'tick', undefined), [1]);
});

test('an already-aborted signal rejects with an AbortError', async () => {
  const emitter = new EventEmitter();
  const controller = new AbortController();
  controller.abort();
  const outcome = await waitFor(emitter, 'never', controller.signal).then(
    () => 'resolved',
    (error) => error.name
  );
  eq(outcome, 'AbortError');
});

test('aborting while you wait rejects', async () => {
  const emitter = new EventEmitter();
  const controller = new AbortController();
  const waiting = waitFor(emitter, 'never', controller.signal);
  const outcome = waiting.then(() => 'resolved', (error) => error.name);
  setTimeout(() => controller.abort(), 10);
  eq(await outcome, 'AbortError');
  eq(emitter.listenerCount('never'), 0);
});

test('it leaves no listener behind once it settles', async () => {
  const emitter = new EventEmitter();
  setTimeout(() => emitter.emit('ready'), 5);
  await waitFor(emitter, 'ready');
  eq(emitter.listenerCount('ready'), 0);
  eq(emitter.listenerCount('error'), 0);
});

test("an 'error' event rejects with that error", async () => {
  const emitter = new EventEmitter();
  const waiting = waitFor(emitter, 'ready');
  setTimeout(() => emitter.emit('error', new Error('socket died')), 5);
  const message = await waiting.then(
    () => 'resolved',
    (error) => error.message
  );
  eq(message, 'socket died');
  ok(emitter.listenerCount('error') === 0, 'and it unsubscribes');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('an async listener that resolves records nothing', async () => {
  const { bus, errors } = createBus();
  bus.on('job', async () => 'fine');
  bus.emit('job');
  await sleep(10);
  eq(errors, []);
});

test('an async listener that rejects lands in errors', async () => {
  const { bus, errors } = createBus();
  bus.on('job', async () => {
    throw new Error('db down');
  });
  bus.emit('job');
  await sleep(10);
  eq(errors.length, 1);
  eq(errors[0].message, 'db down');
});

test('the recorded value is the rejection reason itself', async () => {
  const { bus, errors } = createBus();
  const reason = new Error('the very same object');
  bus.on('job', async () => {
    throw reason;
  });
  bus.emit('job');
  await sleep(10);
  ok(errors[0] === reason, 'expected the identical Error instance');
});

test('the other listeners still run when one of them rejects', async () => {
  const { bus, errors } = createBus();
  const ran = [];
  bus.on('job', async () => {
    throw new Error('first failed');
  });
  bus.on('job', async () => {
    ran.push('second');
  });
  bus.emit('job');
  await sleep(10);
  eq(ran, ['second']);
  eq(errors.length, 1);
});

test('the rejection arrives later, not during emit()', async () => {
  const { bus, errors } = createBus();
  bus.on('job', async () => {
    throw new Error('later');
  });
  bus.emit('job');
  eq(errors.length, 0, 'emit() returns before the promise settles');
  await sleep(10);
  eq(errors.length, 1);
});

test('emit() reports whether anyone was listening', async () => {
  const { bus, errors } = createBus();
  eq(bus.emit('job'), false);
  bus.on('job', async () => 'ok');
  eq(bus.emit('job'), true);
  await sleep(10);
  eq(errors, []);
});

test('a listener that throws SYNCHRONOUSLY is not captured', async () => {
  const { bus, errors } = createBus();
  bus.on('job', () => {
    throw new Error('sync boom');
  });
  throws(() => bus.emit('job'), 'sync boom');
  await sleep(10);
  eq(errors, [], 'captureRejections only covers returned promises');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('collects the values emitted before the abort, in order', async () => {
  const emitter = new EventEmitter();
  const controller = new AbortController();
  const collecting = collectUntilAborted(emitter, 'tick', controller.signal);
  await sleep(5);
  emitter.emit('tick', 'a');
  await sleep(5);
  emitter.emit('tick', 'b');
  await sleep(5);
  controller.abort();
  eq(await collecting, ['a', 'b']);
});

test('a synchronous burst is buffered, not dropped', async () => {
  const emitter = new EventEmitter();
  const controller = new AbortController();
  const collecting = collectUntilAborted(emitter, 'tick', controller.signal);
  await sleep(5);
  emitter.emit('tick', 1);
  emitter.emit('tick', 2);
  emitter.emit('tick', 3);
  await sleep(5);
  controller.abort();
  eq(await collecting, [1, 2, 3]);
});

test('an abort with nothing emitted gives an empty list', async () => {
  const emitter = new EventEmitter();
  const controller = new AbortController();
  const collecting = collectUntilAborted(emitter, 'tick', controller.signal);
  await sleep(5);
  controller.abort();
  eq(await collecting, []);
});

test('an already-aborted signal returns an empty list right away', async () => {
  const emitter = new EventEmitter();
  const controller = new AbortController();
  controller.abort();
  eq(await collectUntilAborted(emitter, 'tick', controller.signal), []);
});

test('it unsubscribes when it stops', async () => {
  const emitter = new EventEmitter();
  const controller = new AbortController();
  const collecting = collectUntilAborted(emitter, 'tick', controller.signal);
  await sleep(5);
  emitter.emit('tick', 1);
  ok(emitter.listenerCount('tick') > 0, 'it should be listening while it runs');
  await sleep(5);
  controller.abort();
  await collecting;
  eq(emitter.listenerCount('tick'), 0);
});

test('the abort is swallowed — it resolves, it does not reject', async () => {
  const emitter = new EventEmitter();
  const controller = new AbortController();
  const collecting = collectUntilAborted(emitter, 'tick', controller.signal);
  await sleep(5);
  emitter.emit('tick', 'only');
  await sleep(5);
  controller.abort();
  const outcome = await collecting.then(
    (values) => values,
    (error) => `rejected: ${error.name}`
  );
  eq(outcome, ['only']);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('deadline() gives a signal that has not fired yet', () => {
  const signal = deadline(50);
  ok(signal instanceof AbortSignal, 'expected an AbortSignal');
  eq(signal.aborted, false);
});

test('the deadline signal aborts itself with a TimeoutError', async () => {
  const signal = deadline(20);
  await sleep(45);
  eq(signal.aborted, true);
  eq(signal.reason.name, 'TimeoutError');
});

test('firstOf aborts as soon as one input does, with its reason', () => {
  const slow = new AbortController();
  const fast = new AbortController();
  const combined = firstOf([slow.signal, fast.signal]);
  eq(combined.aborted, false);
  fast.abort(new Error('user navigated away'));
  eq(combined.aborted, true);
  eq(combined.reason.message, 'user navigated away');
});

test('firstOf is already aborted when one input already is', () => {
  const done = new AbortController();
  done.abort(new Error('too late'));
  const combined = firstOf([done.signal, new AbortController().signal]);
  eq(combined.aborted, true);
  eq(combined.reason.message, 'too late');
});

test('runChain runs every step and returns their names', async () => {
  const ran = [];
  const steps = ['load', 'transform', 'save'].map((n) => makeStep(n, ran));
  const signal = new AbortController().signal;
  eq(await runChain(steps, { signal, cleanup: () => {} }), [
    'load',
    'transform',
    'save',
  ]);
  eq(ran, ['load', 'transform', 'save']);
});

test('cleanup runs exactly once on the happy path', async () => {
  const ran = [];
  const cleanup = spy();
  const signal = new AbortController().signal;
  await runChain([makeStep('only', ran)], { signal, cleanup });
  eq(cleanup.callCount, 1);
});

test('an abort partway through stops the next step', async () => {
  const ran = [];
  const controller = new AbortController();
  const steps = [
    makeStep('one', ran),
    makeStep('two', ran, () => controller.abort(new Error('cancelled'))),
    makeStep('three', ran),
  ];
  await rejects(
    () => runChain(steps, { signal: controller.signal, cleanup: () => {} }),
    'cancelled'
  );
  eq(ran, ['one', 'two']);
});

test('cleanup still runs when the chain is aborted', async () => {
  const ran = [];
  const cleanup = spy();
  const controller = new AbortController();
  const steps = [
    makeStep('one', ran, () => controller.abort(new Error('stop'))),
    makeStep('two', ran),
  ];
  await rejects(() => runChain(steps, { signal: controller.signal, cleanup }));
  eq(cleanup.callCount, 1);
  eq(ran, ['one']);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('uppercases a single chunk', async () => {
  eq(await run(['hello']), 'HELLO');
});

test('joins many chunks, in order, despite the delay', async () => {
  eq(await run(['ab', 'cd', 'ef']), 'ABCDEF');
});

test('an empty source produces an empty string', async () => {
  eq(await run([]), '');
});

test('digits and punctuation come through untouched', async () => {
  eq(await run(['a1-', 'b2!']), 'A1-B2!');
});

test('Buffer chunks are handled too', async () => {
  eq(await run([Buffer.from('ab'), Buffer.from('cd')]), 'ABCD');
});

test('shout is an async generator you can drive by hand', async () => {
  const out = [];
