test('Buffer chunks work the same way', async () => {
  const { stream, written } = makeSink({ highWaterMark: 1 });
  await writeAll(stream, [Buffer.from('ab'), Buffer.from('cd')]);
  eq(written, ['ab', 'cd']);
});

